---FillCf
---填充数据
---@param line integer @ 行
---@param row integer @ 列
---@param data table @ jsonData 服务器数据
function MazeMapPointDojo:FillCf(line, row, data)
    self.line = tonumber(line)
    self.row = tonumber(row)
    

    if self.type == Constants.MazePointType.StartPoint then 
        self.miniMapPos = Vector3(self.row * 24, (self.line - 1) * 28 + 14, 0) * 1.5
        self.viewMapPos = Vector3(self.row * 90, (self.line - 1) * 120 + 39, 0) * 1.5
    elseif self.type == Constants.MazePointType.BossBattle then
        self.miniMapPos = Vector3(self.row * 24, (self.line - 1) * 28 + 14*3, 0) * 1.5
        self.viewMapPos = Vector3(self.row * 90, (self.line - 1) * 120 + 39 * 3, 0) * 1.5
    else
        self.miniMapPos = Vector3(self.row * 24, (self.line - 1) * 28 + 14 *2, 0) * 1.5
        self.viewMapPos = Vector3(self.row * 90, (self.line - 1) * 120 + 39 * 2, 0) * 1.5
    end

    local posTab = CfUtils.Split(CfUtils.GetCfData(AutoIds.IdSetting354, (self.line).."", "row"..self.row))
    self.pos = {[1] = posTab[1], [2] = posTab[2], [3] = posTab[3]}

    --事件数据
    if data then
        if isSet(data, "type") then
            self.type = data.type
        end
        if isSet(data, "questId") then
            self.questId = data.questId
        end
        if isSet(data, "difficultyFix") then
            self.difficultyFix = data.difficultyFix
        end
        if isSet(data, "eventId") then
            self.eventId = data.eventId
        end
        if isSet(data, "goods") then
            self.goods = data.goods
        end
        if isSet(data, "assistants") then
            self.assistants = data.assistants
        end
    end
end

--设置通关类型
function MazeMapPointDojo:SetPasssType(type)
    if not type then
        return
    end
    self.passType = checkNumber(type)
end

return MazeMapPointDojo